const results = [];

for (let i = 0; i < items.length; i++) {
  // 1. Force n8n to read the file from disk
  const binaryBuffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  // 2. Convert to Base64
  const base64String = binaryBuffer.toString('base64');
  const mimeType = items[i].binary.data.mimeType;

  // 3. Construct the exact same output JSON to preserve downstream compatibility
  const outputJson = {
    ...items[i].json, 
    base64_img_string: base64String,
    base64_img_string_mime: mimeType
  };

  results.push({ json: outputJson });

  // 4. 📡 GUI PROGRESS BROADCAST (Fire & Forget)
  const config = outputJson.config || {};
  if (config.enable_gui_logging === true && config.gui_webhook_url) {
      try {
          const firestorePayload = {
              job_id: config.job_id, 
              phase_id: outputJson.PHASE_ID || "3", 
              agent_id: "scaffolding_generator", 
              status: "running",
              timestamp: new Date().toISOString(),
              base64_img_string: base64String
          };

          await this.helpers.httpRequest({
              method: 'POST',
              url: config.gui_webhook_url,
              headers: { 'Content-Type': 'application/json' },
              body: firestorePayload,
              json: true,
              timeout: 1500 
          });
      } catch (e) { 
          // Ignore timeouts/errors so the pipeline continues to Phase 4
      }
  }
}

return results;

