const finalPayload = {
    ...safeData,
    phase_id: "-", 
    agent_id: "-", 
    task_id: "-", 
    status: "completed", 
    timestamp: new Date().toISOString()
};

// 3. Fire the "Fat JSON" to the Cloud Run Listener
if (config.enable_gui_logging === true && webhookUrl) {
    try {
        await this.helpers.httpRequest({
            method: 'POST',
            url: webhookUrl,
            headers: { 'Content-Type': 'application/json' },
            body: finalPayload,
            json: true,
            timeout: 5000
        });
    } catch (e) {
        console.error("Final broadcast failed:", e.message);
    }
}

return [{ json: { status: "Workflow Complete", job_id: finalData.job_id } }];

