        ...input,
        PHASE_ID: "", // Set target Phase ID here
        AGENT_ID: "", // Set target Agent ID here
        TASK_ID: nextTask
    }
}];

const input = items[0].json;
const config = input.config || $('Load Phase 3 Config').item.json.config;

const needs3D = input.needs_3d_planning === true;
const needsPrim = input.needs_arrangement_planning === true;

let combinedDirectives = [];

// 2. Navigate to the scaffolding_designer tasks in the config
const tasks = config.phases["3"].agents.scaffolding_designer.tasks;

// 3. Parse the JSON strings from the config to extract just the text
if (needs3D) {
    const rawResult3D = JSON.parse(tasks.inject_3d_constraints.result);
    combinedDirectives.push(rawResult3D.situational_directives);
}

if (needsPrim) {
    const rawResultPrim = JSON.parse(tasks.inject_primitives_constraints.result);
    combinedDirectives.push(rawResultPrim.situational_directives);
}

// 4. If no directives are needed, set TASK_ID to skip
if (combinedDirectives.length === 0) {
    return [{
        json: {
            ...input,
            TASK_ID: "skip"
        }
    }];
}

// 5. Pass the combined string into the 'directives' variable for the UA to inject
return [{
    json: {
        ...input,
        PHASE_ID: "3",
        AGENT_ID: "scaffolding_designer", 
        TASK_ID: "inject_multiple_constraints",
        directives: combinedDirectives.join("\n\n") // Maps directly to $directives
    }
}];

// === 🐛 CFG INJECT EXECUTION ERROR ===
const inputData = items[0].json;

// 1. Extract the specific error
let errorText = "Unknown Error";
if (inputData.error) {
    if (inputData.error.message) {
        errorText = inputData.error.message;
    } else if (inputData.error.response && inputData.error.response.data) {
        const rawData = inputData.error.response.data;
        errorText = typeof rawData === 'object' ? JSON.stringify(rawData) : rawData.toString();
    }
}

// 2. Format the Multiline Context
const formattedError = `While attempting to execute python code:
*** PYTHON RUNTIME ERROR ***
The code crashed with this error:
${errorText}`;

// 3. Clean Payload (Remove raw error object)
const cleanData = { ...inputData };
delete cleanData.error; 

// 4. Set routing for the Global Error Injector
return [{
    json: {
        ...cleanData,
        PHASE_ID: "-",
        AGENT_ID: "error_injector",
        TASK_ID: "log_error",
        error_text: formattedError // The UA will swap this into $error_text
    }
}];
